import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Badge dimensions (small capsule)
  const badgeWidth = 0.7;
  const badgeHeight = 0.32;

  // Create main badge geometry
  const badgeGeom = new THREE.PlaneGeometry(badgeWidth, badgeHeight);

  // Load ceramic grain texture
  const grainTexture = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  grainTexture.colorSpace = THREE.SRGBColorSpace;

  // Main badge material (basic, no lighting)
  const badgeMaterial = new THREE.MeshBasicNodeMaterial({
    map: grainTexture,
    color: new THREE.Color(config.colors?.accent || '#ff2a38'),
  });

  const badge = new THREE.Mesh(badgeGeom, badgeMaterial);
  badge.position.set(
    config.scenePosition[0],
    config.scenePosition[1],
    config.scenePosition[2]
  );

  group.add(badge);

  // Store original position for hover animation
  const originalY = badge.position.y;

  // Create edge accent (emissive glow layer)
  const edgeGeom = new THREE.PlaneGeometry(badgeWidth + 0.06, badgeHeight + 0.06);
  const edgeMaterial = new THREE.MeshStandardNodeMaterial({
    color: new THREE.Color(config.colors?.accent || '#ff2a38'),
    emissive: new THREE.Color(config.colors?.accent || '#ff2a38'),
    emissiveIntensity: 0.3,
    metalness: 0,
    roughness: 1,
    transparent: true,
    opacity: 0,
  });

  const edge = new THREE.Mesh(edgeGeom, edgeMaterial);
  edge.position.z = -0.001;
  badge.add(edge);

  // Interaction state tracking
  let isHovering = false;
  let isFocused = false;

  // Attach event handlers
  badge.userData.handlers = {
    hover: () => {
      if (isHovering) return;
      isHovering = true;

      // rise-in effect: y + 0.15, power3.out, 0.7s
      gsap.to(badge.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });

      // Show edge accent
      gsap.to(edgeMaterial, {
        opacity: 0.5,
        duration: 0.5,
        ease: 'power2.out',
      });
    },

    hoverOut: () => {
      isHovering = false;

      // Return to original position
      gsap.to(badge.position, {
        y: originalY,
        duration: 0.7,
        ease: 'power3.out',
      });

      // Hide edge accent if not focused
      if (!isFocused) {
        gsap.to(edgeMaterial, {
          opacity: 0,
          duration: 0.5,
          ease: 'power2.out',
        });
      }
    },

    click: () => {
      // press-down effect: scale 0.97, 120ms, back.out
      const tl = gsap.timeline();
      tl.to(badge.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
      }).to(
        badge.scale,
        {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power2.out',
        },
        0.12
      );

      // Emit navigation event
      if (config.emit) {
        config.emit('hub-pricing.select');
      }
    },

    focus: () => {
      isFocused = true;

      // Accent edge on focus
      gsap.to(edgeMaterial, {
        opacity: 1,
        duration: 0.3,
        ease: 'power2.out',
      });
    },

    blur: () => {
      isFocused = false;

      // Remove accent if not hovering
      if (!isHovering) {
        gsap.to(edgeMaterial, {
          opacity: 0,
          duration: 0.3,
          ease: 'power2.out',
        });
      }
    }
  };

  // Cleanup function
  group.userData.cleanup = () => {
    gsap.killTweensOf(badge.position);
    gsap.killTweensOf(badge.scale);
    gsap.killTweensOf(edgeMaterial);

    grainTexture.dispose();
    badgeGeom.dispose();
    badgeMaterial.dispose();
    edgeGeom.dispose();
    edgeMaterial.dispose();
  };

  return group;
}
